//! Compare original writer/reader roundtrip with controlled Rust projections.
use spore_core::{cell_restore_writer_gate_v1::{self as writer,mode_zero_bytes},cell_stream_word_read_v1 as word,cell_restore_stream_gate_v1::{self as gate,Resolver}};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let mut a=std::env::args().skip(1);let b=std::fs::read(a.next().expect("native stdout")).unwrap();let obj=u32::from_str_radix(&a.next().expect("synthetic object"),16).unwrap();let input=u32::from_str_radix(&a.next().expect("synthetic input"),16).unwrap();let backend=u32::from_str_radix(&a.next().expect("synthetic backend plus eight"),16).unwrap();assert_eq!(b.len(),192);for i in 0..4{let present=i%2==1;let cw=if i>=2{0x37f}else{0x27f};let wr=writer::project(true,if present{Some((obj,0xabcdef00))}else{None},if present{Some(true)}else{None},Some(true),true).unwrap();let payload:Vec<_>=wr.words.iter().map(|&v|u32::from_le_bytes(mode_zero_bytes(v))).collect();let first=word::project(0,input,true,Some((4,payload[0])),true).unwrap();let second=if present{Some(word::project(0,backend,true,Some((4,payload[1])),true).unwrap())}else{None};let rd=gate::project(true,0xa5a5a5a5,Some(first.destination),second.as_ref().map(|v|v.destination),if present{Some(Resolver{succeeded:true,slot_after:obj})}else{None},Some(true),cw,0x1f80,true).unwrap();let r=&b[i*48..(i+1)*48];assert_eq!((w(r,0),w(r,4),w(r,8),w(r,12),w(r,16),w(r,20),w(r,24),w(r,28),w(r,32)),(u32::from(rd.returned),u32::from(wr.returned),rd.slot,(payload.len()*4)as u32,(payload.len()*4)as u32,payload[0],payload.get(1).copied().unwrap_or(0xa5a5a5a5),wr.after,2));let fp=w(r,36);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,40)&!0x3f,0x1f80);assert_eq!(w(r,44),0xa5a5a5a5);}println!("matched four synthetic in-memory original writer/reader roundtrips");}
